#!/usr/bin/env python3
"""Prepare one explicit free-trip context; root executes and merges the receipt."""
from pathlib import Path
import json,sys,subprocess,os
HERE=Path(__file__).resolve().parent;PLUGIN=HERE.parent/'figma-plugin';sid=sys.argv[1];spec=next(s for s in json.loads((HERE.parent/'data/free-travel-flow-states.json').read_text())if s['id']==sid);cloud=json.loads((HERE/'state.json').read_text());bundle=json.JSONDecoder().raw_decode((PLUGIN/'code.js').read_text().split('const BUNDLE = ',1)[1])[0]
bundle['screens']=[];bundle.update(freeTravelStates=[spec],freeTravelPassport=json.loads((HERE.parent/'data/free-travel-passport.json').read_text()),flowRepairStates=[],npcFlowStates=[],sceneBytes={},iconSvgs={},iconNodeIds={},assetNames={});bundle['sceneHashes'].update(cloud.get('sceneHashes',{}));bundle.pop('avatarAssets',None);bundle.pop('avatarControlIcons',None);bundle.pop('cropDexData',None)
files=['src.js','current-fixes.js','legacy-fixes.js','hud-navigation-fixes.js','current-qa-fixes.js','hud-lightweight-fixes.js','p2p3-visual-fixes.js']
source=subprocess.check_output(['node',str(HERE/'filter_source.cjs'),'screens:general|GIFT-SENT,'+sid,*[str(PLUGIN/f)for f in files]],text=True)+'\n'+(PLUGIN/'free-travel-flow-fixes.js').read_text()
source+='\n'+(PLUGIN/'overlay-cleanup-fixes.js').read_text()
state={k:cloud[k]for k in ['pageId','libraryId','variables','styles','kit','icons','overlayIndex']};state['variables']={k:v for k,v in state['variables'].items()if not k.startswith(('bag/','kitchen/','container/','p0bag/'))};state['icons']={k:v for k,v in state['icons'].items()if k.startswith('i-')};state['kit']={k:v for k,v in state['kit'].items()if not k.startswith(('Reference','FacilityMarker/','Compact/Kitchen/','Avatar','NoteSelection/','LegacyCollectionCell/','LegacyGearSlot/'))}
restore=(HERE/'legacy-adapter-restore.js.txt').read_text().replace('__STATE__',json.dumps(state,separators=(',',':')));restore+='\nfor(const n of PAGE.children){if(n.type!=="FRAME")continue;const col=Math.round((n.x-3560)/400),row=Math.round((n.y-180)/900);if(col>=0&&col<3&&row>=0&&Math.abs(n.x-(3560+col*400))<1&&Math.abs(n.y-(180+row*900))<1)overlayIndex=Math.max(overlayIndex,row*3+col+1);}'
tail='''await wire();await Promise.all(STYLE_JOBS);return {...legacyNewNodeIds(),mutatedNodeIds:[],freeTravelScreens:LEDGER.freeTravelScreens,freeTravelSceneScreens:LEDGER.freeTravelSceneScreens,overlayIndex,warnings:LEDGER.warnings,overlays:LEDGER.overlays,checks:LEDGER.checks.freeTravel,mainScreenCount:Object.keys(LEDGER.screens).length};'''
code='const BUNDLE='+json.dumps(bundle,ensure_ascii=False,separators=(',',':'))+';\n'+source+'\n'+restore+'\n'+tail;dest=Path(os.environ.get('GENSEN_CLOUD_OUTPUT',str(HERE/('free-travel-'+sid+'.js'))));dest.write_text(code);subprocess.run(['node',str(HERE/'minify.cjs'),str(dest)],check=True);subprocess.run(['node',str(HERE/'preflight_script.cjs'),str(dest)],check=True);print(json.dumps({'id':sid,'file':str(dest),'bytes':dest.stat().st_size,'figmaExecuted':False}))
